update public.learning_paths
set
  title = 'History and Systems of Psychology',
  goal = 'History and Systems of Psychology',
  summary = 'Frame psychology''s history as an active interpretation of ideas, institutions, evidence, power, and professional identity. Topics trace questions about mind, knowledge, body, soul, behavior, and experience before laboratory science; how measurement, sensory science, physiology, and evolution helped make psychology scientific; structuralism, functionalism, Gestalt psychology, psychoanalysis, and behaviorism; measurement, testing, and applied psychology; humanistic and existential thought; the cognitive revolution; biological, neuroscience, evolutionary, and embodied perspectives; professional psychology; who was included, excluded, studied, pathologized, and erased; and psychology as a pluralistic science navigating integration, ethics, reproducibility, culture, technology, and public impact.',
  data = $hsysjson${"slug": "history-and-systems-of-psychology", "title": "History and Systems of Psychology", "description": "Frame psychology's history as an active interpretation of ideas, institutions, evidence, power, and professional identity. Topics trace questions about mind, knowledge, body, soul, behavior, and experience before laboratory science; how measurement, sensory science, physiology, and evolution helped make psychology scientific; structuralism, functionalism, Gestalt psychology, psychoanalysis, and behaviorism; measurement, testing, and applied psychology; humanistic and existential thought; the cognitive revolution; biological, neuroscience, evolutionary, and embodied perspectives; professional psychology; who was included, excluded, studied, pathologized, and erased; and psychology as a pluralistic science navigating integration, ethics, reproducibility, culture, technology, and public impact.", "topics": [{"id": "cc73d2fe-3ef6-4498-a9e6-0051dc612389", "type": "topic", "title": "Historiography, Psychology as a Science, and Why History Matters", "description": "Frame psychology's history as an active interpretation of ideas, institutions, evidence, power, and professional identity.", "children": [{"id": "14b72ef3-86c8-4ec5-a34b-b5c34aab5778", "type": "subtopic", "title": "Historiography of psychology", "children": [{"id": "bdee37c5-6f35-46db-ab99-833e1404408c", "type": "concept", "title": "Presentism"}, {"id": "f4b9c1c8-2bac-4857-bfe7-cd631959dc1f", "type": "concept", "title": "Great-person history"}, {"id": "f78aba06-25be-4cd3-86fd-fddf822ad895", "type": "concept", "title": "Zeitgeist explanations"}, {"id": "f8521a05-8387-4027-836f-99ead5a42d34", "type": "concept", "title": "Internal vs external history"}], "description": "Historiography helps students see that histories are argued interpretations, not neutral timelines."}, {"id": "e9513fcd-595c-4e2a-849b-af8a02991fdc", "type": "subtopic", "title": "Psychology as a science", "children": [{"id": "fda992d0-e49e-4803-87a9-f90f38660a68", "type": "concept", "title": "Observation and measurement"}, {"id": "25d8e979-603a-4d23-95a2-4390765f3407", "type": "concept", "title": "Experimentation"}, {"id": "ea3346b6-b6a8-4777-906c-1467fc9240a3", "type": "concept", "title": "Theory and evidence"}, {"id": "0e43adc4-f1bb-43e7-8504-5f6379cdd36d", "type": "concept", "title": "Replication and cumulative science"}], "description": "This subtopic asks what made psychology scientific and why that status has always been contested."}, {"id": "61dcbe3f-b3ac-4580-b416-e55872bc5f7f", "type": "subtopic", "title": "Uses of disciplinary history", "children": [{"id": "b2d86fb0-b08b-4def-bbdb-52381154f241", "type": "concept", "title": "Conceptual roots"}, {"id": "244e9cad-79cf-48f9-bf76-57c1ab0c1f87", "type": "concept", "title": "Professional memory"}, {"id": "e56f0fea-94c9-4f4c-9521-c44756fc510c", "type": "concept", "title": "Ethical reflection"}, {"id": "1cf3e199-2254-4ff7-a834-3f680d47e5c6", "type": "concept", "title": "Systems comparison"}], "description": "History helps students understand current debates, professional identities, and ethical responsibilities."}]}, {"id": "3bdccf74-0afb-45dd-9657-82097a0af69a", "type": "topic", "title": "Pre-Scientific Roots and Philosophy of Mind", "description": "Trace psychology's questions about mind, knowledge, body, soul, behavior, and experience before it became a laboratory science.", "children": [{"id": "c04e26e5-74f9-43cc-88c9-e596410526fc", "type": "subtopic", "title": "Ancient and classical foundations", "children": [{"id": "3db4b23e-1dda-4521-a340-75e5a0478697", "type": "concept", "title": "Plato"}, {"id": "5a87c964-5352-48e8-99d3-0179d05bb3dd", "type": "concept", "title": "Aristotle"}, {"id": "2cb40068-08e2-423c-a780-eeca1e88e48f", "type": "concept", "title": "Stoicism"}, {"id": "552a2b44-e6d0-4ce0-8ae7-54dbafcf898c", "type": "concept", "title": "Mind-body questions"}], "description": "Early philosophy supplied enduring questions about mind, reason, perception, habit, and character."}, {"id": "f709a9ec-8cd6-4262-a7e6-3f445c731de3", "type": "subtopic", "title": "Early modern philosophy", "children": [{"id": "39188e38-118e-4338-82ee-675e4b5eda02", "type": "concept", "title": "Descartes"}, {"id": "3fdbf6dd-2761-4885-88fa-b7deb7954977", "type": "concept", "title": "Locke"}, {"id": "f7b89bf1-d6ee-430c-80ca-2bd174807dfd", "type": "concept", "title": "Hume"}, {"id": "59cd34ca-a0c4-4aa1-be7b-aba2e68e3055", "type": "concept", "title": "Kant"}], "description": "Modern psychology inherited debates about knowledge, mind, experience, and mechanism."}, {"id": "7c51c5fa-cbef-448f-9f7a-bf03ca1b5f08", "type": "subtopic", "title": "Philosophy of mind and moral science", "children": [{"id": "3d7184a5-2cf4-46df-8949-287a725c76df", "type": "concept", "title": "Rationalism"}, {"id": "b9bfdeeb-97e0-4a19-8afd-48556c45b21a", "type": "concept", "title": "Empiricism"}, {"id": "93f16eb7-f062-45df-b4af-d6ec800f884e", "type": "concept", "title": "Associationism"}, {"id": "88dcf276-3c02-447f-a395-90fb4167a19b", "type": "concept", "title": "Faculty psychology"}], "description": "Before psychology separated from philosophy, mental life was studied through introspection, moral philosophy, and theories of human nature."}]}, {"id": "2f682905-bfb8-4907-b112-520066cc4eba", "type": "topic", "title": "Psychophysics, Physiology, Evolution, and the Birth of Experimental Psychology", "description": "Understand how measurement, sensory science, physiology, and evolution helped make psychology scientific.", "children": [{"id": "11e595c3-c320-46fd-8e54-ac244bc602ae", "type": "subtopic", "title": "Psychophysics", "children": [{"id": "697fe3e2-f0c9-4d02-91ed-5163d0155efb", "type": "concept", "title": "Weber"}, {"id": "85827cf1-58a5-4a43-84b9-b6617686e96c", "type": "concept", "title": "Fechner"}, {"id": "3201adac-d603-49a0-be15-da5ff3238693", "type": "concept", "title": "Thresholds"}, {"id": "e827ee67-123c-497d-b4d8-ac0d34075210", "type": "concept", "title": "Just noticeable difference"}], "description": "Psychophysics showed that subjective experience could be related to measurable physical stimuli."}, {"id": "b2be47c1-7fad-43f5-b2d7-18b9b5176b78", "type": "subtopic", "title": "Physiology and nervous system science", "children": [{"id": "8b98dc00-955d-4b0f-a332-575f9015efc7", "type": "concept", "title": "Helmholtz"}, {"id": "5e854e82-9211-4d36-9d2a-c227634cc334", "type": "concept", "title": "Muller"}, {"id": "5415d5bc-76dc-4a17-b8bc-1e34ba382b6f", "type": "concept", "title": "Reaction time"}, {"id": "22c7ab18-cd92-42d0-a7a3-6c00c7211039", "type": "concept", "title": "Localization debates"}], "description": "Physiology gave psychology tools and models for studying sensation, reflexes, and brain-behavior relations."}, {"id": "5bc7e51b-c233-49cd-8333-44f44b96c57f", "type": "subtopic", "title": "Evolution and adaptation", "children": [{"id": "88468b07-beb4-4e6b-b82e-d7c9b1347dbf", "type": "concept", "title": "Darwin"}, {"id": "1cadfa0f-1aa7-4dae-a3b6-069afda9b3f1", "type": "concept", "title": "Comparative psychology"}, {"id": "4eb4749e-c201-49d4-8878-f43cf519fc5c", "type": "concept", "title": "Adaptation"}, {"id": "4ee8c348-4d59-4da2-8302-85ce7e95fd59", "type": "concept", "title": "Individual differences"}], "description": "Darwinian thinking reframed mind and behavior as adaptive, comparative, developmental, and continuous with other animals."}]}, {"id": "27e7b359-c5a8-43e9-b869-0669b204dcd9", "type": "topic", "title": "Structuralism, Introspection, and the First Psychology Laboratories", "description": "Study Wundt, Titchener, and early laboratory psychology as attempts to analyze conscious experience systematically.", "children": [{"id": "9a9e5a05-4ffe-449b-ad59-cf2015bf26e0", "type": "subtopic", "title": "Wundt and laboratory psychology", "children": [{"id": "9e90e2fa-d5b1-4507-b1d8-62f4cda7fbcd", "type": "concept", "title": "Leipzig laboratory"}, {"id": "0ba6213c-322a-4f64-a73e-bdc19057d1a0", "type": "concept", "title": "Voluntarism"}, {"id": "1d9b9afa-3bad-495a-a355-042128374e54", "type": "concept", "title": "Experimental introspection"}, {"id": "c650c29a-f28c-4808-b85b-76d4dc6a60ca", "type": "concept", "title": "Mental chronometry"}], "description": "Wundt's laboratory symbolized psychology's institutional break from philosophy."}, {"id": "d9abfb03-018a-4e96-bfd2-a8da9818025a", "type": "subtopic", "title": "Titchener and structuralism", "children": [{"id": "2ddf9906-3d21-4dcf-ac93-757e24da0f05", "type": "concept", "title": "Sensations"}, {"id": "fbb16bb7-e3a6-4f9c-a7fb-8b3c437d06ac", "type": "concept", "title": "Images"}, {"id": "c9832382-9a13-47bd-a7f4-af364ada274c", "type": "concept", "title": "Affections"}, {"id": "7bde0e86-4104-4ecf-ae87-de5aba769a0c", "type": "concept", "title": "Trained introspection"}], "description": "Structuralism tried to identify the basic elements of conscious experience."}, {"id": "44b42611-4cd2-4ff0-8452-353d709e44ff", "type": "subtopic", "title": "Limits of introspection", "children": [{"id": "c02efab3-c65e-4ea3-a0c7-08ce8029c777", "type": "concept", "title": "Replicability concerns"}, {"id": "017c0a0d-c07b-420a-8587-6b5c90da9fc7", "type": "concept", "title": "Observer training"}, {"id": "79e59060-f38e-4ac8-93f3-6081d2c56eb9", "type": "concept", "title": "Private experience"}, {"id": "08a01585-64fe-4d41-816a-6175d2d9354c", "type": "concept", "title": "Methodological disputes"}], "description": "Critiques of introspection helped drive later systems toward behavior, function, and objective methods."}]}, {"id": "78dff923-ac90-4db5-bbc6-a9a4f9460062", "type": "topic", "title": "Functionalism, Pragmatism, and American Psychology", "description": "Explore how James, Dewey, and functionalists shifted psychology toward adaptation, purpose, education, and applied life.", "children": [{"id": "68edac54-9a19-44f3-a8a3-bb9e0a96e675", "type": "subtopic", "title": "William James and pragmatism", "children": [{"id": "ef032ce0-5ff1-4c6d-820c-179329fb9e70", "type": "concept", "title": "Stream of consciousness"}, {"id": "08c0e5bd-2bf1-4ca7-a73b-89f3c11d0d75", "type": "concept", "title": "Habit"}, {"id": "9150df6d-421d-4661-9b8e-b6ec170255bb", "type": "concept", "title": "James-Lange theory"}, {"id": "e3f58666-7a99-45f3-8951-a10c7e25c657", "type": "concept", "title": "Pragmatism"}], "description": "James emphasized stream of consciousness, habit, emotion, and the practical functions of mind."}, {"id": "de58702f-61aa-4658-bd03-cd986a61277e", "type": "subtopic", "title": "Functionalism", "children": [{"id": "39a569f2-57db-46ed-be4e-23e1708b3b58", "type": "concept", "title": "Adaptation"}, {"id": "5d235901-093b-4ee9-9a6b-97ad1cf6ba02", "type": "concept", "title": "Purpose"}, {"id": "fe045c60-ac79-43e9-86ce-ffdc9618d0f0", "type": "concept", "title": "Individual differences"}, {"id": "7583d3e3-501c-49d5-b84f-81e55debb03b", "type": "concept", "title": "Applied orientation"}], "description": "Functionalism asked what mental processes do for organisms adapting to environments."}, {"id": "58ab8c9b-ed97-4cbc-b2ff-5c0a41a0bb3c", "type": "subtopic", "title": "American institutions and applications", "children": [{"id": "f61209c5-3ae5-497c-8615-6417432878f3", "type": "concept", "title": "Dewey"}, {"id": "d8374ccc-19ba-47d0-959a-89e0722d3a39", "type": "concept", "title": "Education"}, {"id": "c8f0bc32-4fc8-4b37-8bea-00eecf2f36fd", "type": "concept", "title": "Child study"}, {"id": "fd7a870c-d2c4-4888-a9ee-cae0ed6da20f", "type": "concept", "title": "Applied psychology"}], "description": "Functionalism helped psychology enter schools, clinics, workplaces, and public life."}]}, {"id": "8fb1560f-88a1-4dab-b71a-d977206bf7ae", "type": "topic", "title": "Gestalt Psychology and Holistic Perception", "description": "Learn how Gestalt psychology challenged elementism by emphasizing organization, perception, insight, and whole patterns.", "children": [{"id": "7af61109-1e0b-49d6-96da-594fe5da5115", "type": "subtopic", "title": "Gestalt principles", "children": [{"id": "d537e11b-1f5d-474c-b2e5-4737ce8b3e2c", "type": "concept", "title": "Figure-ground"}, {"id": "a97a715b-276d-49e1-976d-67b2882869e1", "type": "concept", "title": "Similarity"}, {"id": "80f0e205-2680-42b6-b9c4-506c1971ae49", "type": "concept", "title": "Proximity"}, {"id": "940e02b3-92ce-4d48-b07c-2f706c4ff935", "type": "concept", "title": "Closure"}], "description": "Gestalt psychology showed that perception is organized into meaningful wholes, not built only from isolated elements."}, {"id": "dd38c843-303d-471e-9ed6-b48c1d8c203b", "type": "subtopic", "title": "Insight and problem solving", "children": [{"id": "63fe733a-2feb-4023-b3e0-e5e39938a481", "type": "concept", "title": "Kohler"}, {"id": "b89bd504-3283-44ab-9848-e70b83df7183", "type": "concept", "title": "Insight"}, {"id": "b472adaf-4716-4cab-a199-8c02bd479aa3", "type": "concept", "title": "Restructuring"}, {"id": "26fc60c7-e317-498e-ba1f-0ea29ea2d4a9", "type": "concept", "title": "Productive thinking"}], "description": "Gestalt theorists used problem solving to challenge trial-and-error accounts of learning."}, {"id": "2f0258ee-f323-49db-be7d-01800e4cfd73", "type": "subtopic", "title": "Legacy of Gestalt ideas", "children": [{"id": "1669b8be-e492-4598-9170-72fbf57ac92a", "type": "concept", "title": "Perceptual organization"}, {"id": "0e895487-3ba0-4383-bf73-0db667706685", "type": "concept", "title": "Cognitive restructuring"}, {"id": "b47b34d4-0495-408f-a44f-eb806b056082", "type": "concept", "title": "Field theory"}, {"id": "78197d45-6acf-4ce5-b381-0039b9d829df", "type": "concept", "title": "Human factors and design"}], "description": "Gestalt principles shaped perception, cognition, therapy, design, and systems thinking."}]}, {"id": "79257126-7f56-4810-ae79-0924598a05ae", "type": "topic", "title": "Psychoanalysis, Psychodynamic Thought, and the Unconscious", "description": "Examine Freud, neo-Freudians, and psychodynamic traditions as theories of conflict, meaning, development, and therapy.", "children": [{"id": "14edf68c-7d40-4f60-8afd-2709048f37aa", "type": "subtopic", "title": "Freud and psychoanalysis", "children": [{"id": "170ba086-8560-4ed3-9aaa-ca729acc4e96", "type": "concept", "title": "Unconscious"}, {"id": "01385a90-d923-4806-a119-050cac5a3071", "type": "concept", "title": "Defense mechanisms"}, {"id": "dc2ef07e-7454-45b4-bfc0-b5f095b761a4", "type": "concept", "title": "Psychosexual development"}, {"id": "f9a440b9-a475-4e9f-a1ef-677e238dcd70", "type": "concept", "title": "Dreams and symptoms"}], "description": "Psychoanalysis offered a theory of unconscious conflict, development, symptoms, and treatment."}, {"id": "1ab445ee-63b3-41c9-9234-e3bbf18a2aec", "type": "subtopic", "title": "Neo-Freudians and revisions", "children": [{"id": "7062ddc6-096d-48a9-972f-da0e578be3da", "type": "concept", "title": "Jung"}, {"id": "2757b3ab-2620-4835-808e-632296602d19", "type": "concept", "title": "Adler"}, {"id": "8c943332-6508-4ab9-86c0-2c7651610436", "type": "concept", "title": "Horney"}, {"id": "abf6e514-5b07-489d-9468-d15e687bb8e9", "type": "concept", "title": "Erikson"}], "description": "Later psychodynamic thinkers revised Freud toward culture, relationships, ego development, and social life."}, {"id": "51099a28-db3b-44d6-a721-27305d274545", "type": "subtopic", "title": "Critique and legacy", "children": [{"id": "9a318719-e0ca-4e36-8d26-308e617cf181", "type": "concept", "title": "Evidence debates"}, {"id": "1b6554ec-29ba-4fd5-984c-83ee284e371e", "type": "concept", "title": "Clinical influence"}, {"id": "af546ecf-1ce0-46f0-b9d4-b2d5b32dd202", "type": "concept", "title": "Culture and literature"}, {"id": "d34742ca-03a9-4193-8de8-a5ae6621aad5", "type": "concept", "title": "Modern psychodynamic therapy"}], "description": "Students evaluate psychoanalysis as historical system, clinical tradition, cultural force, and contested science."}]}, {"id": "b38e0165-60eb-4f8d-a4b8-8f9f8e225e5b", "type": "topic", "title": "Behaviorism, Learning Theory, and the Science of Observable Behavior", "description": "Analyze how Watson, Skinner, Pavlov, Hull, and Tolman reshaped psychology around behavior, learning, and prediction.", "children": [{"id": "380f5454-a6e4-437d-a1c3-42e4c935957d", "type": "subtopic", "title": "Watson and methodological behaviorism", "children": [{"id": "52061aad-5d7a-4a9f-9c2b-53da5dbe61cc", "type": "concept", "title": "Watson"}, {"id": "c8282d8f-a393-4c31-985d-5dd4d35af44d", "type": "concept", "title": "Conditioning"}, {"id": "9806e251-5562-470a-8ed7-576c9e3de943", "type": "concept", "title": "Environmentalism"}, {"id": "d14af650-83d0-4ed8-a9b5-6c8472218bf8", "type": "concept", "title": "Anti-introspection"}], "description": "Behaviorism tried to make psychology objective by focusing on observable behavior."}, {"id": "1e4307d9-b847-43da-9a51-8b07dab9c7a7", "type": "subtopic", "title": "Learning theory", "children": [{"id": "574a5f22-9861-40a7-bb76-d246c73eb4c7", "type": "concept", "title": "Pavlov"}, {"id": "45394774-8ba6-42f0-ae0f-e82fb0000753", "type": "concept", "title": "Thorndike"}, {"id": "f61d3f2d-eeda-44f8-bdcd-5d712d34cbce", "type": "concept", "title": "Hull"}, {"id": "49238a79-8f3e-4490-afb1-e5c38d2b6c87", "type": "concept", "title": "Tolman"}], "description": "Learning theorists developed powerful models of association, reinforcement, and behavior change."}, {"id": "c01ec0fe-69da-48ab-854d-ceda38eeabca", "type": "subtopic", "title": "Skinner and radical behaviorism", "children": [{"id": "7ddd874c-ed33-4ad4-8765-fb2d3563cae2", "type": "concept", "title": "Reinforcement"}, {"id": "6c00e3fc-e064-4773-933b-df92b9912ddc", "type": "concept", "title": "Shaping"}, {"id": "4ba27353-b0fd-4901-8ee9-013ee52110bf", "type": "concept", "title": "Schedules of reinforcement"}, {"id": "6716d896-9b48-4136-a331-a638e73fc019", "type": "concept", "title": "Behavior modification"}], "description": "Skinner extended behaviorism into operant conditioning, behavior analysis, and social applications."}]}, {"id": "ea1591ff-01f3-4763-83a8-f34182470301", "type": "topic", "title": "Measurement, Testing, Intelligence, Personality, and Applied Psychology", "description": "Study how psychological measurement, testing, industrial, educational, military, and clinical applications shaped the field.", "children": [{"id": "90f47425-78a6-4384-aef9-755cc2d48f61", "type": "subtopic", "title": "Mental testing and intelligence", "children": [{"id": "d6c7dee7-be1d-485f-b43d-0d5077ba6ada", "type": "concept", "title": "Binet"}, {"id": "e82a4e2e-0973-4e2d-93c3-898f9fd5725e", "type": "concept", "title": "IQ testing"}, {"id": "fde1e2bd-1255-4ff5-9614-e3ec2c51fb76", "type": "concept", "title": "Army Alpha and Beta"}, {"id": "2eabdbf5-8f83-4b67-8e22-04be243ba948", "type": "concept", "title": "Eugenics and misuse"}], "description": "Testing shaped education, military selection, clinical classification, and debates over heredity, culture, and fairness."}, {"id": "c988a751-19fb-4ed6-b459-601b6cd131e1", "type": "subtopic", "title": "Personality and assessment", "children": [{"id": "1dddae53-562a-4c4f-9f93-3ac96010a2ae", "type": "concept", "title": "Trait theory"}, {"id": "0437df33-f7a2-4087-80b3-9c9e300538e0", "type": "concept", "title": "Projective tests"}, {"id": "54c0fdc5-7711-48dc-abed-c1836dfb2750", "type": "concept", "title": "Factor analysis"}, {"id": "89d9ca74-d6d6-4ae0-8377-f3e78617e0f8", "type": "concept", "title": "Validity and reliability"}], "description": "Personality systems tried to classify stable individual differences and clinical patterns."}, {"id": "d6cb7e64-6493-4894-90a3-c62ebf7343f1", "type": "subtopic", "title": "Applied psychology", "children": [{"id": "ae828001-1841-4211-bc8c-cf6ee4a9a2e5", "type": "concept", "title": "Industrial-organizational psychology"}, {"id": "6715f8f2-24d5-4629-88ec-f399c38fe19d", "type": "concept", "title": "Educational psychology"}, {"id": "8e603ead-043f-4ea6-9a80-9b4a0a7adfba", "type": "concept", "title": "Clinical assessment"}, {"id": "01d424c5-7aff-4753-8771-00f144e5ca41", "type": "concept", "title": "Human factors"}], "description": "Applied psychology expanded the discipline into workplaces, schools, courts, health, and public policy."}]}, {"id": "4b52a171-034d-438d-9ee9-efb9d88b01cd", "type": "topic", "title": "Humanistic, Existential, and Third-Force Psychology", "description": "Understand how Maslow, Rogers, and existential-humanistic thinkers responded to psychoanalysis and behaviorism.", "children": [{"id": "31aa01aa-fbf6-497c-8437-04feb2edc04d", "type": "subtopic", "title": "Humanistic psychology", "children": [{"id": "ff09a99c-4099-4ecc-954c-531b2a4cb5a0", "type": "concept", "title": "Maslow"}, {"id": "1bd4b8e8-e1a7-486c-9549-9cc0dade9bd9", "type": "concept", "title": "Rogers"}, {"id": "12b9f81b-6dd6-4d45-8d84-be9f479aefc4", "type": "concept", "title": "Self-actualization"}, {"id": "46d07e30-1838-4746-9a88-910e280715f6", "type": "concept", "title": "Person-centered therapy"}], "description": "Humanistic psychology centered growth, meaning, agency, and subjective experience."}, {"id": "bbd102af-9251-490d-931e-b6575a422457", "type": "subtopic", "title": "Existential psychology", "children": [{"id": "3f61c0b2-5eb1-4123-afcb-6b0713d4f641", "type": "concept", "title": "May"}, {"id": "0c548877-d570-4d7a-bc9d-9373c9fffefe", "type": "concept", "title": "Frankl"}, {"id": "f054f44a-58d5-4b88-9402-ecd78df4e48c", "type": "concept", "title": "Authenticity"}, {"id": "b8ec2a68-89d9-440b-a957-78986ea1b639", "type": "concept", "title": "Meaning-making"}], "description": "Existential approaches emphasized freedom, responsibility, death, isolation, and meaning."}, {"id": "3a4d3055-59d1-4694-9a7c-70a8af0e8392", "type": "subtopic", "title": "Legacy and critique", "children": [{"id": "989a002a-5225-4cc6-93ad-b622ced7d7f2", "type": "concept", "title": "Therapeutic alliance"}, {"id": "541a8d73-aa8c-4cc9-9d91-225b9e4d4913", "type": "concept", "title": "Client-centered practice"}, {"id": "50e200da-7d76-43b1-ad55-3c51482077c6", "type": "concept", "title": "Positive psychology"}, {"id": "0f1b2bc2-91e7-49a9-a16d-43632d9253f6", "type": "concept", "title": "Scientific critique"}], "description": "Humanistic ideas influenced therapy, education, organizations, and positive psychology while raising questions about measurement."}]}, {"id": "7f12430d-3c0d-4680-85f1-2ebaba32336c", "type": "topic", "title": "The Cognitive Revolution and Information-Processing Psychology", "description": "Trace the return of mind through language, memory, computation, artificial intelligence, and cognitive science.", "children": [{"id": "0e3a72fe-5c41-4b29-95e4-3f9cf9f16092", "type": "subtopic", "title": "Origins of the cognitive revolution", "children": [{"id": "a673c47b-3107-4d63-ad6e-390ce3a50e4d", "type": "concept", "title": "Chomsky"}, {"id": "bc8bc918-7a68-4bbf-ab17-3a2ade4745a7", "type": "concept", "title": "Miller"}, {"id": "cc6d201f-8f49-4a28-af9c-60ac99b36d3d", "type": "concept", "title": "Bruner"}, {"id": "61f10649-5ade-4368-9c31-12208ef026bd", "type": "concept", "title": "Computer metaphor"}], "description": "The cognitive revolution restored mental processes as legitimate scientific targets."}, {"id": "2de0cdc5-de85-446f-a5d9-52b62d02cb42", "type": "subtopic", "title": "Information-processing models", "children": [{"id": "e369e130-e98a-443f-a7e3-3dacca550f45", "type": "concept", "title": "Encoding"}, {"id": "bf9d2876-aad4-4dd0-882f-22c1b1bb2bf5", "type": "concept", "title": "Storage and retrieval"}, {"id": "41a3d194-a9f9-4d60-964b-c27883879360", "type": "concept", "title": "Working memory"}, {"id": "399cfcd1-09fa-41c1-a4e1-97229ce5c849", "type": "concept", "title": "Symbolic computation"}], "description": "Information-processing psychology gave researchers models of attention, memory, language, and problem solving."}, {"id": "d59e135f-9c37-4877-8ff2-107efb213998", "type": "subtopic", "title": "Cognitive science", "children": [{"id": "c90e8c9c-1f84-48d7-af84-22706093c326", "type": "concept", "titl