avior."}, {"id": "759373cb-161f-4a03-a526-88ddb4c28588", "type": "subtopic", "title": "Embodied and situated cognition", "children": [{"id": "7302c10a-2d23-40f8-b865-7bb8b1a42c74", "type": "concept", "title": "Embodiment"}, {"id": "da1db4d6-556e-43a6-8855-8cd63748e979", "type": "concept", "title": "Affordances"}, {"id": "e3bc7996-e066-4b15-89db-06941d5ce590", "type": "concept", "title": "Situated cognition"}, {"id": "cb1eb1c9-8d5f-49dc-93a6-61cbbdfc0223", "type": "concept", "title": "Extended mind debates"}], "description": "Embodied approaches challenged purely computational views by emphasizing body, action, environment, and culture."}]}, {"id": "8f27dcee-315e-4998-9a38-ee8deaa1f68a", "type": "topic", "title": "Clinical, Counseling, Community, and Professional Psychology History", "description": "Follow psychology's development as a profession through assessment, psychotherapy, ethics, training, and public service.", "children": [{"id": "9e91f8e3-55d8-4963-9bdf-3ecbeee12097", "type": "subtopic", "title": "Clinical psychology's development", "children": [{"id": "832ccb01-4dc7-4700-b2a1-315907bfca89", "type": "concept", "title": "Lightner Witmer"}, {"id": "dc77fbec-6648-4eff-8da8-ddecf8cb66c2", "type": "concept", "title": "Veterans and war psychology"}, {"id": "91178be2-4355-4755-9bdc-2bcb99e23056", "type": "concept", "title": "Scientist-practitioner model"}, {"id": "f0357bc6-4af9-4400-a209-64cd6d4c78f2", "type": "concept", "title": "PsyD and PhD models"}], "description": "Clinical psychology grew through assessment, treatment, war service, hospitals, and professional training."}, {"id": "f05c4d98-99b9-44a6-9c34-9080e32650e1", "type": "subtopic", "title": "Psychotherapy systems", "children": [{"id": "fee601ac-e3e3-4d45-b295-daa9a39876bc", "type": "concept", "title": "Psychodynamic therapy"}, {"id": "80493cb6-fab1-4ffa-9bb3-0d67a1e709ab", "type": "concept", "title": "Behavior therapy"}, {"id": "11d19fbc-786a-4d38-a00a-1203d47d972d", "type": "concept", "title": "Cognitive therapy"}, {"id": "6e87c308-6d76-4785-985e-f24c83d95662", "type": "concept", "title": "Integrative therapy"}], "description": "Therapy history shows how competing models of change emerged and blended."}, {"id": "750a54c6-deff-4b25-976a-d7826d92b17d", "type": "subtopic", "title": "Ethics and professionalization", "children": [{"id": "f6418d91-913d-4d54-ae98-6cfa09cbc8dd", "type": "concept", "title": "APA ethics"}, {"id": "76116a52-19b5-46fc-9d46-79948eb97c82", "type": "concept", "title": "Licensure"}, {"id": "b3a93bc2-5dc4-4441-8c6f-a4b485a38733", "type": "concept", "title": "Evidence-based practice"}, {"id": "d3c95f89-0815-4878-b3a5-4f2cb8151ba9", "type": "concept", "title": "Cultural competence"}], "description": "Professional psychology developed standards for competence, ethics, training, and public accountability."}]}, {"id": "59464e75-7b42-4859-aab7-7fa044d42207", "type": "topic", "title": "Diversity, Exclusion, Global Psychologies, and Critical Histories", "description": "Examine who was included, excluded, studied, pathologized, and erased in psychology's historical development.", "children": [{"id": "ec5705dc-45d5-4e88-9e41-c79c243380c9", "type": "subtopic", "title": "Race, gender, class, and exclusion", "children": [{"id": "8ff7c112-e5ba-4dfe-b3f6-4d66b96d3484", "type": "concept", "title": "Women in psychology"}, {"id": "ad8cd804-d5f2-428c-91e8-c0d7ebdffd3a", "type": "concept", "title": "Psychology and race"}, {"id": "b125a94e-f058-448a-abab-e3c35de49530", "type": "concept", "title": "Class and access"}, {"id": "fe7ba74e-39ad-47d1-87c7-38e07ba0cfc7", "type": "concept", "title": "Institutional exclusion"}], "description": "Critical history reveals how psychology both challenged and reproduced social hierarchies."}, {"id": "e9f9512a-2719-4b6b-901e-98a4ac0abe06", "type": "subtopic", "title": "Critical works and corrective histories", "children": [{"id": "9ceb2bfb-b110-47bd-aa18-0c6eb94772a2", "type": "concept", "title": "Even the Rat Was White"}, {"id": "